package net.battlespades.bot;
import java.util.*;
import java.util.function.*;
import net.battlespades.physics.PlayerPhysics.Vector;
import static net.battlespades.bot.BotState.*;
/** Retained bidirectional weighted A*: <=512 expansions/slice and <=32768 discovered/expanded nodes. Guidance is not motor authority. */
public final class SurfaceCorridorSearch {
    @FunctionalInterface public interface SurfaceAt {Integer get(int x,int y,int support);}
    @FunctionalInterface public interface Layers {List<Integer> get(int x,int y);}
    private record Entry(double priority,int node,double cost) implements Comparable<Entry>{public int compareTo(Entry e){int c=Double.compare(priority,e.priority);if(c==0)c=Integer.compare(node,e.node);return c==0?Double.compare(cost,e.cost):c;}}
    private record Link(int source,int target){}
    private final Thread owner=Thread.currentThread();private final byte[] supports;private final int width,height,area,start,target;private final SurfaceAt surfaceAt;private final Layers layers;
    private final Set<Link> blocked=new HashSet<>();private final PriorityQueue<Entry> forward=new PriorityQueue<>(),backward=new PriorityQueue<>();private final Map<Integer,Double> costs=new HashMap<>(),backCosts=new HashMap<>();private final Map<Integer,Integer> parents=new HashMap<>(),children=new HashMap<>();private final Set<Integer> closed=new HashSet<>(),backClosed=new HashSet<>();private boolean done;private int expansions;private List<Vector> path=List.of();
    public SurfaceCorridorSearch(byte[] supports,int width,int height,int start,int target,Set<Edge> exclusions,SurfaceAt surfaceAt,int startHeight,int targetHeight,Layers layers){if(width<=0||height<=0||width>512||height>512||supports.length!=(long)width*height||start<0||start>=supports.length||target<0||target>=supports.length)throw new IllegalArgumentException("Invalid corridor dimensions/endpoints");this.supports=supports.clone();this.width=width;this.height=height;area=width*height;this.surfaceAt=surfaceAt;this.layers=layers;this.start=node(start,startHeight);this.target=node(target,targetHeight);for(var edge:exclusions)exclude(edge);if(level(this.start)>=239||level(this.target)>=239){done=true;return;}costs.put(this.start,0.);backCosts.put(this.target,0.);forward.add(new Entry(0,this.start,0));backward.add(new Entry(0,this.target,0));}
    private void owned(){if(Thread.currentThread()!=owner)throw new IllegalStateException("Corridor search outside worker");}private int column(int node){return node%area;}private int level(int node){return surfaceAt==null?supports[node]&255:node/area;}private int node(int col,int height){return surfaceAt==null?col:col+height*area;}
    public void exclude(Edge edge){owned();var a=edge.source();var b=edge.target();blocked.add(new Link(node(a.y()*width+a.x(),a.z()),node(b.y()*width+b.x(),b.z())));}
    public boolean done(){owned();return done;}public int expansions(){owned();return expansions;}public List<Vector> path(){owned();return path;}
    public void advance(){owned();for(int i=0;i<512;i++){if(done)return;if(forward.isEmpty()||backward.isEmpty()||expansions>=32768){finish(null);return;}if(forward.size()<=backward.size())expandForward();else expandBackward();}}
    private double estimate(int x,int y,int support,int end){int col=column(end);return (Math.abs(x-col%width)+Math.abs(y-col/width)+Math.abs(support-level(end))*.4)*1.25;}
    private List<Integer> neighbors(int current){int col=column(current),x=col%width,y=col/width;var result=new ArrayList<Integer>(4);if(x+1<width)result.add(col+1);if(y+1<height)result.add(col+width);if(x>0)result.add(col-1);if(y>0)result.add(col-width);return result;}
    private void expandForward(){var e=forward.remove();int current=e.node();expansions++;if(e.cost()!=costs.get(current)||closed.contains(current))return;closed.add(current);if(current==target||backClosed.contains(current)){finish(current);return;}int level=level(current);for(int col:neighbors(current)){int x=col%width,y=col/width;Integer support;if(surfaceAt==null)support=supports[col]&255;else support=surfaceAt.get(x,y,level);if(support==null)continue;int neighbor=node(col,support),rise=support-level;if(closed.contains(neighbor)||support>=239||rise< -2||rise>1||blocked.contains(new Link(current,neighbor)))continue;double candidate=e.cost()+1+Math.abs(rise)*.4;if(candidate>=costs.getOrDefault(neighbor,Double.POSITIVE_INFINITY))continue;if(!costs.containsKey(neighbor)&&costs.size()+backCosts.size()>=32768){finish(null);return;}costs.put(neighbor,candidate);parents.put(neighbor,current);forward.add(new Entry(candidate+estimate(x,y,support,target),neighbor,candidate));}}
    private void expandBackward(){var e=backward.remove();int current=e.node();expansions++;if(e.cost()!=backCosts.get(current)||backClosed.contains(current))return;backClosed.add(current);if(current==start||closed.contains(current)){finish(current);return;}int support=level(current),col=column(current),x=col%width,y=col/width;for(int nc:neighbors(current)){int nx=nc%width,ny=nc/width;for(int previous:stepsOnto(x,y,support,nx,ny)){if(backClosed.contains(previous)||blocked.contains(new Link(previous,current)))continue;int before=level(previous);double candidate=e.cost()+1+Math.abs(support-before)*.4;if(candidate>=backCosts.getOrDefault(previous,Double.POSITIVE_INFINITY))continue;if(!backCosts.containsKey(previous)&&costs.size()+backCosts.size()>=32768){finish(null);return;}backCosts.put(previous,candidate);children.put(previous,current);backward.add(new Entry(candidate+estimate(nx,ny,before,start),previous,candidate));}}}
    private List<Integer> stepsOnto(int x,int y,int level,int nx,int ny){int col=ny*width+nx;var result=new ArrayList<Integer>();if(surfaceAt==null){int support=supports[col]&255,rise=level-support;if(support<239&&rise>=-2&&rise<=1)result.add(col);return result;}List<Integer> candidates=layers==null?java.util.stream.IntStream.range(level-1,level+3).boxed().toList():layers.get(nx,ny);for(int support:candidates){if(support<level-1||support>Math.min(level+2,238)||layers==null&&!Objects.equals(surfaceAt.get(nx,ny,support),support))continue;if(Objects.equals(surfaceAt.get(x,y,support),level))result.add(node(col,support));}return result;}
    private void finish(Integer meeting){if(meeting!=null){var nodes=new ArrayList<Integer>();nodes.add(meeting);while(nodes.getLast()!=start)nodes.add(parents.get(nodes.getLast()));Collections.reverse(nodes);while(nodes.getLast()!=target)nodes.add(children.get(nodes.getLast()));for(int i=1;i<nodes.size();i++)if(blocked.contains(new Link(nodes.get(i-1),nodes.get(i)))){finish(null);return;}var points=new ArrayList<Vector>();int last=0;for(int i=0;i<nodes.size();i++){int node=nodes.get(i);if(i==0||i==nodes.size()-1||i-last>=8||node-nodes.get(i-1)!=nodes.get(i+1)-node||level(node)!=level(nodes.get(i-1))||level(node)!=level(nodes.get(i+1))){int col=column(node);points.add(new Vector(col%width+.5,col/width+.5,level(node)-2.25));last=i;}}path=List.copyOf(points);}done=true;forward.clear();backward.clear();costs.clear();backCosts.clear();parents.clear();children.clear();closed.clear();backClosed.clear();}
}
